 public function testRealSourceAndHeldResultRemainNonexecutingInCompanion():void {
  self::assertTrue(class_exists(HeldPreparationReadModel::class));self::assertTrue(class_exists(HeldPreparationPanel::class));$port=new NativePortAdapter(NativeBridge::connect('1.0.0'),getenv('DF_NATIVE_TEST_SHA'));self::assertSame(getenv('DF_NATIVE_TEST_SHA'),$port->contractManifest()['core_source_sha']);self::assertSame('1.0.0',NativeBusinessMutationEvidence::version());$f=$this->businessMutationFixture($this->fixture);$http=0;$guard=static function()use(&$http){++$http;throw new RuntimeException('Provider HTTP denied');};add_filter('pre_http_request',$guard,PHP_INT_MAX);
  try{$e=PrintifyApiApprovalFixture::checked(NativeBusinessMutationEvidence::resolve($f['scope'],1,$f['mapping_id'],$f['spec_id'],$f['plan_hash']));$view=HeldPreparationReadModel::observe($f['scope'],1,$e);self::assertNotWPError($view);self::assertSame($f['business_version_id'],$view['business_product_version_id']);self::assertNull($view['native_product_version']);self::assertFalse($view['companion_payload_equivalence_verified']);self::assertFalse($view['mutation_authorized']);
