   global $wpdb;$wpdb->query('COMMIT');$wpdb->query('SET autocommit=1');foreach(NativeHeldJournalSchema::statements()as $sql)self::assertNotFalse($wpdb->query($sql));$r=PrintifyApiApprovalFixture::checked(NativeBusinessMutationEvidence::register($f['scope'],1,$f['mapping_id'],$f['spec_id'],$f['plan_hash'],$e['evidence_hash']));$held=HeldPreparationReadModel::fromRegistration($f['scope'],1,$r);self::assertNotWPError($held);self::assertSame('HELD_SOURCE_ONLY',$held['state']);self::assertFalse($held['trusted_receipt']);self::assertFalse($held['network_request_permitted']);self::assertNull($held['native_product_version']);self::assertSame($held,HeldPreparationReadModel::fromRegistration($f['scope'],1,PrintifyApiApprovalFixture::checked(NativeBusinessMutationEvidence::register($f['scope'],1,$f['mapping_id'],$f['spec_id'],$f['plan_hash'],$e['evidence_hash']))));self::assertSame(['PANEL','GET_READ'],$port->contractManifest()['capabilities']);self::assertTrue(DigiForge\Core\Settings::get('stop_all',true));self::assertTrue(DigiForge\Core\Settings::safety_locked());
   self::assertWPError(NativeBusinessMutationEvidence::register($f['scope'],1,$f['mapping_id'],$f['spec_id'],$f['plan_hash'],str_repeat('f',64)));WP_Session_Tokens::get_instance(1)->destroy(wp_get_session_token());self::assertWPError(NativeBusinessMutationEvidence::resolve($f['scope'],1,$f['mapping_id'],$f['spec_id'],$f['plan_hash']));self::assertSame(0,$http);
  }finally{remove_filter('pre_http_request',$guard,PHP_INT_MAX);}
